   "jsx": "/* Jjodel Default View 2.1 */ \n<View className={'root'}>\n    <div className={'door'}>\n        {data.$ownedShelves.values.map(shelf => (\n            <DefaultNode data={shelf}/>\n        ))}\n    </div>\n\n    {/* New: The Coin Insert Box */}\n    <div \n    className={`coin-insert-container ${data.state &&data.state.show_insert_coins ? 'active' : ''}`}\n    onClick={() => {\n        data.state = { \n            'show_insert_coins': !(data.state && data.state.show_insert_coins) \n        };\n    }}\n    >\n        <div className={'coin-button'}></div>\n        <div className={'coin-slot'}></div>\n    </div>\n    <div className={'display-container'}>\n        <DefaultNode data={data.$panel.value.$display.value}/>\n    </div>\n    <div className={'numpad-container'}>\n        <DefaultNode data={data.$panel.value.$numPad.value}/>\n    </div>\n    {/* The Item Delivery Bin */}\n    <div className={'pickup-container'}>\n        <DefaultNode data={data.$pickUpBox.value}/>\n    </div>\n\n    {/* The Coin Return Slot */}\n    <div className={'coin-return-container'}>\n        <DefaultNode data={data.$coinController.value.$coinChange.value}/>\n    </div>\n</View>",
   "css": "&>.root {\n\n    background-color: #3484c5;\n    background-image: linear-gradient(135deg, #3484c5 0%, #2a6da3 100%);\n    box-shadow:\n\n        inset -80px 0 40px -20px rgba(0,0,0,0.2),\n\n        10px 10px 30px rgba(0,0,0,0.3);\n\n    padding: 0px 0px 0px 0px;\n\n    display: grid;\n\n    grid-template-columns: 1fr 160px;\n\n    gap: 0px;\n\n    border-radius: 4px;\n\n    position: relative;\n\n    border: 2px solid #225a87;\n\n    align-items: start;\n\n    overflow: hidden;\n\n\n\n    &::before {\n\n        content: \"\";\n\n        position: absolute;\n\n        top: 0;\n\n        bottom: 0;\n\n        left: calc(100% - 170px);\n\n        width: 10px;\n\n        background-color: rgba(0, 0, 0, 0.15);\n\n        border-left: 1px solid #225a87;\n\n        z-index: 1;\n\n    }\n\n\n\n    /* Updated Metallic Base / Grill */\n\n    &::after {\n\n        content: \"\";\n\n        position: absolute;\n\n        bottom: 0;\n\n        left: 0;\n\n        right: 0;\n\n        height: 80px;\n\n        z-index: 3;\n\n        border-top: 1px solid #ffffff;\n\n       \n\n        /* Layer 1: The black vents (slats) with padding */\n\n        /* Layer 2: The brushed metal background */\n\n        background:\n\n            repeating-linear-gradient(\n\n                90deg,\n\n                transparent,\n\n                transparent 12px,\n\n                #1a1a1a 12px,\n\n                #1a1a1a 15px\n\n            ) no-repeat center center / 85% 60%,\n\n            linear-gradient(to right, #999 0%, #ddd 20%, #ddd 80%, #999 100%);\n\n       \n\n        box-shadow: inset 0 2px 5px rgba(255,255,255,0.5), inset 0 -10px 20px rgba(0,0,0,0.2);\n\n    }    \n\n\n\n    .door {\n\n        grid-column: 1;\n\n        display: flex;\n\n        flex-direction: column;\n\n        gap: 0px;\n\n        background-color: #1a1a1a;\n\n        border: 12px solid #c0c0c0;\n\n        border-right-width: 15px;\n\n        border-bottom-width: 25px;\n\n        box-shadow:\n\n            inset 0 0 30px #000,\n\n            5px 5px 15px rgba(0,0,0,0.4);\n\n        position: relative;\n\n        height: auto;\n\n        min-height: 400px;\n\n        z-index: 2;\n\n        margin-top: 0px;\n\n        margin-left: 0px;\n\n    }\n    \n.pickup-container {\n        position: absolute;\n        bottom: 110px; /* Sits just above the metallic grill (height 80px + 10px gap) */\n        left: 190px;  \n    }\n    .coin-return-container {\n        position: absolute;\n        right: 43px;\n        bottom: 120px;\n    }\n\n    .coin-insert-container {\n    position: absolute;\n    right: 49px;\n    top: 200px;\n    width: 60px;\n    height: 140px;\n    background: linear-gradient(145deg, #a0a0a0, #707070);\n    border: 2px solid #555;\n    border-radius: 6px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: space-around;\n    padding: 10px 0;\n    box-shadow: \n        inset 1px 1px 2px rgba(255,255,255,0.5),\n        2px 4px 10px rgba(0,0,0,0.4);\n    z-index: 5;\n    cursor: pointer;\n    transition: filter 0.2s ease;\n    &.active {\n        filter: brightness(1.2) contrast(1.1);\n        box-shadow: 0 0 10px rgba(255, 255, 255, 0.2);\n    }\n    \n}\n\n.coin-button {\n    width: 30px;\n    height: 30px;\n    background: radial-gradient(circle at 30% 30%, #d0d0d0, #888);\n    border-radius: 50%;\n    border: 2px solid #666;\n    box-shadow: 1px 2px 3px rgba(0,0,0,0.3);\n}\n\n.coin-slot {\n    width: 10px;\n    height: 60px;\n    background: #1a1a1a;\n    border-radius: 2px;\n    border-left: 2px solid #444;\n    border-top: 2px solid #444;\n    box-shadow: inset 2px 2px 4px rgba(0,0,0,0.8);\n}\n\n.numpad-container{\n    width: 120px;\n    position: absolute;\n    top:200px;\n    right:9px;\n}\n\n.display-container{\n    position: absolute;\n    top:50px;\n    right:15px;\n}\n}\n\n",
   "usage": "(ret)=>{ // scope contains: data, node, view, constants, state\n// ** preparations and default behaviour here ** //\nret.data = data\nret.node = node\nret.view = view\n// data, node, view are dependencies by default. delete the line(s) above if you want to remove them.\n// add preparation code here (like for loops to count something), then list the dependencies below.\n\n// ** declarations here ** //\n\n}",
