    "insertCoin": "(v) => {\n\tconst machine = data.model.allSubObjects.filter(o=>o.instanceof.name=='Machine' && o.$coinController.value.$coinInsert.value.name==data.name).first()\n\tconst coinSlot = machine.$coinDispenser.value.$ownedCoinSlots.values.filter(o=>o.$denomination.value.$value.value==v).first()\n\tif (coinSlot) {coinSlot.$balance.value += 1} else {alert('Denomination not supported')}\n}"
